function validate(input) {
  const [{ UserActivity = [] }] = input;
  const byUser = new Map();
  for (const row of UserActivity) {
    if (row.some((v) => v === null)) return 'UserActivity rows may not contain null.';
    const [user, , start, end] = row;
    if (start > end) return `${user} has an activity that ends before it starts.`;
    const key = user.toLowerCase();
    if (!byUser.has(key)) byUser.set(key, []);
    byUser.get(key).push([start, end]);
  }
  for (const [user, periods] of byUser) {
    periods.sort((a, b) => (a[0] < b[0] ? -1 : a[0] > b[0] ? 1 : 0));
    for (let i = 1; i < periods.length; i++) if (periods[i][0] <= periods[i - 1][1]) return `${user} has two activities at the same time.`;
  }
  return null;
}

