function generate(rand, size) {
  const users = ['Alice', 'Bob', 'Carol', 'Dan', 'Eve'];
  const activities = ['Travel', 'Dancing', 'Reading', 'Hiking', 'Cooking'];
  const small = size === 'small';
  const day = (n) => new Date(Date.UTC(2019, 11, 20) + n * 86400000).toISOString().slice(0, 10);
  const UserActivity = [];
  const userCount = small ? users.length : 400;
  for (let u = 0; u < userCount && UserActivity.length < (small ? 8 : 2000); u++) {
    const name = small ? users[u] : `user${u + 1}`;
    const count = small ? Math.floor(rand() * 4) : rand() < 0.15 ? 1 : 2 + Math.floor(rand() * 9);
    let t = Math.floor(rand() * (small ? 20 : 300));
    for (let k = 0; k < count && UserActivity.length < (small ? 8 : 2000); k++) {
      const length = Math.floor(rand() * 5);
      UserActivity.push([name, activities[Math.floor(rand() * activities.length)], day(t), day(t + length)]);
      t += length + 1 + Math.floor(rand() * 4);
    }
  }
  for (let i = UserActivity.length - 1; i > 0; i--) { const j = Math.floor(rand() * (i + 1)); [UserActivity[i], UserActivity[j]] = [UserActivity[j], UserActivity[i]]; }
  return [{ UserActivity }];
}
